<template><div class="confirm-overlay" v-if="show" @click.self="onCancel"><div class="confirm-dialog"><p>{{ msg }}</p><div class="btns"><button @click="onCancel">取消</button><button @click="onOk" class="danger">确认</button></div></div></div></template><script>export default { name: 'ConfirmDialog', data(){return{show:false,msg:'',resolve:null}}, methods:{open(msg){this.msg=msg;this.show=true;return new Promise(r=>{this.resolve=r})},onOk(){this.show=false;this.resolve?.(true)},onCancel(){this.show=false;this.resolve?.(false)}} }</script>
